    # fill color, retaining the other color as background.
    for r in range(h):
        if len(set(grid[r])) == 1:
            k, d = r, grid[r][0]
            panel = grid[:k]
            break
    else:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                k, d = c, grid[0][c]
                panel = [[grid[r][j] for j in range(k)] for r in range(h)]
                break
        else:
            raise ValueError('separator missing')
    colors = set(x for row in panel for x in row) - {0, d}
    # Both noisy colors appear as 2/7 in the left panel of test; choose the
    # more frequent color as the output background and the rarer as foreground.
