    counts = Counter(x for row in panel for x in row if x not in (0, d))
    if len(colors) == 1:
        color = next(iter(colors))
    else:
        color = min(colors, key=counts.get)
    out_h = len(panel)
    out_w = len(panel[0])
    return [[color] * out_w for _ in range(out_h)]
