 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the solid separator and divide the input into corresponding panels.
    for r in range(h):
        if len(set(grid[r])) == 1:
            first, second = grid[:r], grid[r + 1:]
            divider = grid[r][0]
            orientation = 'row'
            break
    else:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                first = [[grid[i][j] for j in range(c)] for i in range(h)]
                second = [[grid[i][j] for j in range(c + 1, w)] for i in range(h)]
                divider = grid[0][c]
                orientation = 'column'
                break
        else:
            raise ValueError('separator not found')

    # Sparse marker on an otherwise blank first panel: the marker's color fills
    # the output panel (as in the sparse-marker demonstration).
    counts = Counter(v for row in first for v in row)
    nonzero = [(v, n) for v, n in counts.items() if v != 0]
    if (orientation == 'row' and 0 in counts and len(nonzero) == 1
            and nonzero[0][1] == 1):
        return [[nonzero[0][0] for _ in row] for row in first]

    if len(first) != len(second) or any(len(a) != len(b) for a, b in zip(first, second)):
        raise ValueError('panels must have matching dimensions')

    shared = ({v for row in first for v in row} &
              {v for row in second for v in row}) - {divider}
    if len(shared) != 1:
        raise ValueError('expected exactly one shared panel color')
    common = next(iter(shared))

    # Recolor the common color to 3 and the other panel color to the common color.
    return [[3 if value == common else common for value in row] for row in first]


